import fs from 'node:fs';
import path from 'node:path';
import {spawnSync} from 'node:child_process';
import {safe, hash, parse, ensure} from './strategic-handoff-io.mjs';
import {assertUserDecisionRequirement} from './user-decision.mjs';

export const RESEARCH_VALIDATOR = '.agents/skills/yss-research/scripts/validate-research-package.mjs';
const binding = (root, ref) => ({ref, digest: hash(fs.readFileSync(safe(root, ref)))});
function readBound(root, bound) {
  ensure(bound && binding(root, bound.ref).digest === bound.digest, 'research-evidence-stale');
  return fs.readFileSync(safe(root, bound.ref));
}
function execute(root, brief, evidence) {
  return spawnSync(process.execPath, [safe(root, RESEARCH_VALIDATOR), safe(root, brief), safe(root, evidence)], {
    cwd: root, encoding: 'utf8', timeout: 30000, maxBuffer: 2 * 1024 * 1024,
    env: {...process.env, NODE_OPTIONS: '', NODE_PATH: ''},
  });
}

/** Capture actual validator output; never overwrite a historical run. */
export function recordResearchVerification(root, brief, evidence, output) {
  const inputs = {brief: binding(root, brief), evidence: binding(root, evidence), validator: binding(root, RESEARCH_VALIDATOR)};
  const dir = safe(root, output, {missing: true});
  ensure(!fs.existsSync(dir), '研究验证输出目录必须不存在');
  const started_at = new Date().toISOString(), result = execute(root, brief, evidence);
  fs.mkdirSync(dir, {recursive: true});
  fs.writeFileSync(path.join(dir, 'stdout.log'), result.stdout || '');
  fs.writeFileSync(path.join(dir, 'stderr.log'), result.stderr || result.error?.message || '');
  const record = {schema_version: 1, kind: 'maintenance-research-verification', inputs,
    command: ['node', RESEARCH_VALIDATOR, brief, evidence], started_at, completed_at: new Date().toISOString(),
    exit_code: result.status, stdout: binding(root, `${output}/stdout.log`), stderr: binding(root, `${output}/stderr.log`)};
  for (const value of Object.values(inputs)) readBound(root, value);
  fs.writeFileSync(path.join(dir, 'verification.json'), JSON.stringify(record, null, 2) + '\n');
  return {binding: binding(root, `${output}/verification.json`), exit_code: result.status};
}

export function validateResearchCompletion(state, {root, continuing = false}) {
  ensure(state?.context_reconciliation?.status === 'not-applicable' && state.context_reconciliation.reason?.trim(), 'research-context-reason-missing');
  fs.readFileSync(safe(root, state.context_reconciliation.ref));
  for (const key of ['blocking_signals', 'drift', 'violation', 'new_impacts', 'stale_candidates']) {
    ensure(Array.isArray(state[key]) && state[key].length === 0, `research-${key}-unresolved`);
  }
  const record = parse(readBound(root, state.research_verification));
  ensure(record.schema_version === 1 && record.kind === 'maintenance-research-verification', 'research-verification-invalid');
  for (const key of ['brief', 'evidence', 'validator']) readBound(root, record.inputs?.[key]);
  ensure(record.inputs.validator.ref === RESEARCH_VALIDATOR, 'research-validator-mismatch');
  ensure(record.exit_code === 0 && Number.isFinite(Date.parse(record.started_at)) && Date.parse(record.completed_at) >= Date.parse(record.started_at), 'research-verification-not-passed');
  ensure(JSON.stringify(record.command) === JSON.stringify(['node', RESEARCH_VALIDATOR, record.inputs.brief.ref, record.inputs.evidence.ref]), 'research-command-mismatch');
  readBound(root, record.stdout); readBound(root, record.stderr);
  for (const ref of [state.context_reconciliation.ref, state.research_verification.ref, record.inputs.brief.ref, record.inputs.evidence.ref]) {
    ensure(state.evidence_refs?.includes(ref), `research-evidence-unreferenced: ${ref}`);
  }
  const current = execute(root, record.inputs.brief.ref, record.inputs.evidence.ref);
  ensure(!current.error && current.status === 0, 'research-current-validation-failed');
  readBound(root, state.research_verification);
  for(const value of Object.values(record.inputs))readBound(root,value);
  if (continuing) {
    const authorization = parse(readBound(root, state.maintenance_authorization));
    ensure(authorization.boundary === 'template-maintenance-scope' && authorization.scope?.includes('work-unit.ssot-update'), 'maintenance-authorization-required');
    assertUserDecisionRequirement(authorization, {root});
  }
  return record;
}
#!/usr/bin/env node
import { readFileSync } from "node:fs";
import path from "node:path";

const PROFILE_VALUES = ["technical-evidence", "strategy-evidence"];
const SOURCE_LEVELS = ["primary", "direct-experience", "near-primary", "secondary", "lead-only"];
const CLAIM_KINDS = ["technical-fact", "user-problem", "business-constraint", "domain-boundary", "business-rule", "mvp", "non-goal", "success-criterion", "stage-decision-basis", "background"];
const STRATEGY_DECISION_KINDS = new Set(["user-problem", "business-constraint", "domain-boundary", "business-rule", "mvp", "non-goal", "success-criterion", "stage-decision-basis"]);

function fail(message) { throw new TypeError(message); }
function requireString(value, label) { if (typeof value !== "string" || !value.trim()) fail(`${label} must be a non-empty string`); }
function requireArray(value, label, nonEmpty = false) { if (!Array.isArray(value) || (nonEmpty && value.length === 0)) fail(`${label} must be ${nonEmpty ? "a non-empty" : "an"} array`); }
function requireChoice(value, choices, label) { if (!choices.includes(value)) fail(`${label} must be one of: ${choices.join(", ")}`); }

function indexed(items, label) {
  const result = new Map();
  items.forEach((item, index) => {
    requireString(item?.id, `${label}[${index}].id`);
    if (result.has(item.id)) fail(`${label} contains duplicate id: ${item.id}`);
    result.set(item.id, item);
  });
  return result;
}

function readEvidence(file) {
  try {
    const value = JSON.parse(readFileSync(file, "utf8"));
    if (!value || typeof value !== "object" || Array.isArray(value)) fail("evidence root must be an object");
    return value;
  } catch (error) {
    if (error instanceof TypeError && error.message === "evidence root must be an object") throw error;
    fail(`${path.basename(file)} must use JSON-compatible YAML 1.2 syntax: ${error.message}`);
  }
}

function validate(briefFile, evidenceFile) {
  if (!briefFile || !evidenceFile) fail("usage: validate-research-package.mjs <brief.md> <evidence.yaml>");
  const briefPath = path.resolve(briefFile);
  const evidencePath = path.resolve(evidenceFile);
  if (path.dirname(briefPath) !== path.dirname(evidencePath)) fail("brief and evidence files must be adjacent");
  if (!briefPath.endsWith("-research-brief.md") || !evidencePath.endsWith("-evidence.yaml")) fail("expected <slug>-research-brief.md and <slug>-evidence.yaml");
  const briefSlug = path.basename(briefPath, "-research-brief.md");
  if (!briefSlug || briefSlug !== path.basename(evidencePath, "-evidence.yaml")) fail("brief and evidence files must use the same non-empty slug");

  const brief = readFileSync(briefPath, "utf8");
  ["Research Scope", "Executive Read", "Findings", "Counter-Signals", "Source Map", "Decision Handoff", "Evidence Limitations"].forEach((heading) => {
    if (!brief.includes(`## ${heading}`)) fail(`brief is missing heading: ## ${heading}`);
  });

  const data = readEvidence(evidencePath);
  if (data.schema_version !== 1) fail("schema_version must be 1");
  requireChoice(data.profile, PROFILE_VALUES, "profile");
  if (data.mode !== "evidence-audited") fail("mode must be evidence-audited");
  ["topic", "audience", "time_horizon"].forEach((field) => requireString(data.scope?.[field], `scope.${field}`));
  ["research_questions", "inclusion_criteria", "exclusion_criteria"].forEach((field) => requireArray(data.scope?.[field], `scope.${field}`, true));
  if (data.ownership?.research_owner !== "yss-research") fail("ownership.research_owner must be yss-research");
  requireString(data.ownership?.downstream_owner, "ownership.downstream_owner");
  if (data.ownership.decision_ref !== null && (typeof data.ownership.decision_ref !== "string" || !data.ownership.decision_ref.trim())) fail("ownership.decision_ref must be null or a non-empty string");

  requireArray(data.search_log, "search_log", true);
  const searches = indexed(data.search_log, "search_log");
  data.search_log.forEach((entry, index) => {
    ["channel", "query_or_corpus", "searched_at"].forEach((field) => requireString(entry[field], `search_log[${index}].${field}`));
    requireChoice(entry.result, ["results-found", "none-found", "access-failed", "excluded"], `search_log[${index}].result`);
  });

  requireArray(data.evidence_items, "evidence_items", true);
  const evidence = indexed(data.evidence_items, "evidence_items");
  data.evidence_items.forEach((item, index) => {
    requireChoice(item.source_level, SOURCE_LEVELS, `evidence_items[${index}].source_level`);
    requireChoice(item.visibility, ["public", "internal"], `evidence_items[${index}].visibility`);
    requireChoice(item.stance, ["support", "counter"], `evidence_items[${index}].stance`);
    ["source_class", "source_ref", "locator", "observed_at", "observation"].forEach((field) => requireString(item[field], `evidence_items[${index}].${field}`));
    requireArray(item.limitations, `evidence_items[${index}].limitations`);
  });

  requireArray(data.claims, "claims", true);
  const claims = indexed(data.claims, "claims");
  data.claims.forEach((claim, index) => {
    requireChoice(claim.claim_kind, CLAIM_KINDS, `claims[${index}].claim_kind`);
    requireString(claim.statement, `claims[${index}].statement`);
    if (typeof claim.decision_bearing !== "boolean") fail(`claims[${index}].decision_bearing must be boolean`);
    requireArray(claim.evidence_refs, `claims[${index}].evidence_refs`, true);
    requireArray(claim.counter_signal_refs, `claims[${index}].counter_signal_refs`, true);
    requireChoice(claim.audit_status, ["supported", "partially-supported", "unsupported", "not-audited"], `claims[${index}].audit_status`);
    requireChoice(claim.confidence, ["low", "medium", "high"], `claims[${index}].confidence`);
    requireChoice(claim.disposition, ["publish", "qualify", "needs-deeper-research"], `claims[${index}].disposition`);

    const supporting = claim.evidence_refs.map((ref) => {
      if (!evidence.has(ref)) fail(`${claim.id} has unresolved evidence ref: ${ref}`);
      const item = evidence.get(ref);
      if (item.stance !== "support") fail(`${claim.id} support ref is not marked support: ${ref}`);
      if (item.source_level === "lead-only") fail(`${claim.id} uses lead-only evidence as support: ${ref}`);
      return item;
    });
    claim.counter_signal_refs.forEach((ref) => {
      if (!evidence.has(ref) && !searches.has(ref)) fail(`${claim.id} has unresolved counter-signal ref: ${ref}`);
      if (evidence.has(ref) && evidence.get(ref).stance !== "counter") fail(`${claim.id} counter-signal evidence is not marked counter: ${ref}`);
      if (searches.has(ref) && searches.get(ref).result !== "none-found") fail(`${claim.id} counter-signal search must have result none-found: ${ref}`);
    });
    if (data.profile === "technical-evidence" && claim.decision_bearing && !supporting.some((item) => item.source_level === "primary")) fail(`${claim.id} is a decision-bearing technical claim without primary evidence`);
    if (data.profile === "strategy-evidence" && STRATEGY_DECISION_KINDS.has(claim.claim_kind) && claim.decision_bearing !== true) fail(`${claim.id} strategy claim kind must be decision-bearing: ${claim.claim_kind}`);
    if (claim.audit_status === "partially-supported" && claim.disposition !== "qualify") fail(`${claim.id} is partially supported and must use qualify`);
    if (claim.audit_status === "unsupported" && claim.disposition !== "needs-deeper-research") fail(`${claim.id} is unsupported and must use needs-deeper-research`);
    if (claim.decision_bearing && claim.audit_status === "unsupported") fail(`${claim.id} is decision-bearing and cannot remain unsupported`);
    if (!brief.includes(claim.id)) fail(`brief does not reference claim: ${claim.id}`);
  });

  requireArray(data.source_gaps, "source_gaps");
  if (data.audit_summary?.status !== "complete") fail("audit_summary.status must be complete");
  requireArray(data.audit_summary.audited_claim_ids, "audit_summary.audited_claim_ids", true);
  requireArray(data.audit_summary.notes, "audit_summary.notes");
  const audited = new Set(data.audit_summary.audited_claim_ids);
  audited.forEach((id) => { if (!claims.has(id)) fail(`audit_summary has unknown claim: ${id}`); });
  claims.forEach((claim, id) => {
    if (claim.decision_bearing && !audited.has(id)) fail(`audit_summary is missing decision-bearing claim: ${id}`);
    if (claim.decision_bearing && claim.audit_status === "not-audited") fail(`${id} remains not-audited`);
  });
  return { claims: claims.size, evidence: evidence.size, searches: searches.size, profile: data.profile };
}

try {
  const result = validate(process.argv[2], process.argv[3]);
  process.stdout.write(`YSS research package valid (${result.profile}, ${result.claims} claims, ${result.evidence} evidence items, ${result.searches} searches)\n`);
} catch (error) {
  process.stderr.write(`YSS research package invalid: ${error.message}\n`);
  process.exitCode = 1;
}
# YSS Research Evidence Contract

This contract defines the persisted `evidence-audited` package. The Markdown brief is the readable narrative; the adjacent evidence file is the source of truth for search execution, provenance, claim mapping, audit state, and downstream ownership.

## Evidence levels

| Level | Meaning | Allowed use |
|---|---|---|
| `primary` | Official specification, official documentation, first-party API, source code, filing, or original dataset | Required for decision-bearing `technical-evidence` claims |
| `direct-experience` | Interview, support record, ticket, direct observation, telemetry, or original user report | May support `strategy-evidence`; state sampling and access limits |
| `near-primary` | Dated review, vendor case study, marketplace record, or a report with inspectable methodology | May support strategy claims with qualification |
| `secondary` | Reputable synthesis that identifies its underlying evidence | Context or corroboration; avoid as the sole basis for high-impact decisions |
| `lead-only` | Aggregator snippet, unattributed repost, or AI-generated summary | Search lead only; never a supporting evidence reference |

## Search and counter-signals

Each material query or corpus inspection has a stable `search-*` ID, execution date, channel, query/corpus, and result. Allowed results are `results-found`, `none-found`, `access-failed`, and `excluded`.

Each claim must name supporting evidence and at least one counter-signal. A counter-signal is either an `evidence-*` item marked `counter` or a `search-*` entry with `none-found`. A `none-found` search only proves that the declared search did not find a counterexample.

## Claim audit

Allowed outcomes:

- `supported`: the evidence directly supports the wording;
- `partially-supported`: only a narrower, qualified wording is supportable;
- `unsupported`: the source does not support the claim;
- `not-audited`: temporary state, forbidden when the package says audit is complete.

`partially-supported` requires disposition `qualify`. `unsupported` requires `needs-deeper-research`. `lead-only` items cannot be cited as support. In `technical-evidence`, every decision-bearing claim needs at least one `primary` supporting item.

In `strategy-evidence`, decision-bearing kinds are `user-problem`, `business-constraint`, `domain-boundary`, `business-rule`, `mvp`, `non-goal`, `success-criterion`, and `stage-decision-basis`. These claims must all be present in `audit_summary.audited_claim_ids` before downstream lifecycle consumption.

## Ownership and failure

The package names its downstream owner and optional decision reference. It does not change the owned artifact or gate. Structure errors, unresolved references, decision-bearing unaudited claims, or a false `complete` declaration fail validation. Access gaps and conflicting evidence are recorded in `source_gaps`; they do not fail the entire brief unless they leave a decision-bearing claim unsupported.

The evidence file uses JSON syntax, which is valid YAML 1.2, so validation is portable and dependency-free.

## Design provenance

The Search Log, evidence passport, and claim-source alignment concepts are adapted from [Academic Research Skills](https://github.com/Imbad0202/academic-research-skills). This YSS contract omits academic writing, publication, fixed agent teams, and cross-model review machinery, and retains YSS lifecycle ownership boundaries.
# 研发文档中文写作规范

起草或修订生命周期文档时，先读本规范的共用写法，再按阶段查阅第 3 节；发送进度与会签提示时读取第 4 节。按当前写入范围应用，正文、摘要和结构化信息应保持同一语义。

[Plan、Spec、Ticket 写作对照](../templates/examples/lifecycle-writing-examples.md)提供同一事实输入下的改写样例；示例不构成真实需求或批准。

## 1. 适用范围与保留项

适用于研究结论、Plan、Spec、产品设计说明、工程契约的解释正文、Ticket、审查、发布和复盘。聊天中的进度通知按第 4 节处理。

本文件是生命周期文档的共用写作规范。生命周期身份、门禁、资产所有权、批准和状态由根 `AGENTS.md` 指定的权威资产决定；标准术语消费根 `CONTEXT.md`。本规范约束表达，不新增阶段、审批或业务规则。

写作调整应保留这些内容的原意：主体、触发条件、规则、例外、量词、范围、非目标、数值及单位、证据引用、未决项、责任人、时点和依赖。稳定 ID、API 标识、schema、metadata、版本及批准记录按原合同保存。已经冻结的内容若需要改变行为，应回交资产所有者处理，不作为润色顺手修改。

## 2. 共用写法

### 先回答读者当前需要判断的问题

开头说明业务问题、本次结论或交付行为。必要背景紧接其后，让读者知道结论为什么成立。正式模板要求的 metadata 和身份信息仍保留；表达顺序的建议不能自行覆盖校验器要求的结构。

只在内容较长或需要导航时添加摘要。摘要引用正文，不另写一套范围和状态；维护时检查二者一致。

### 用主体、条件和结果表达需求

把“提升效率”“完善体验”等目标落实到具体场景：谁在什么情况下做什么，系统产生什么可观察结果。保留支持判断的业务动机，不把所有文字都拆成短句或编号。

输入没有规则时，记录待确认问题；不要为了让句子具体而补出时限、阈值、错误码或默认行为。重要缺口交回拥有该决定的工作单元。非阻断细节按既有流程记录责任人、解决时点和接收方。

### 让确定程度与证据一致

事实给出处；推断说明依据；方案使用建议语气；假设写明如何验证。章节开头已明确整段是假设或建议时，无须每句重复标签。

保留表达真实不确定性的“尚未确认”“可能”“取决于”。只有测试失败现象时，报告现象和下一项诊断，不编造原因；只有期望收益时，写目标和验证方法，不写成已实现收益。估算需有执行者、依据、范围和条件；无依据时不填精确工期。

### 让每段承担一项用途

一段解释一个问题、一项规则或一个取舍。顺序动作使用编号；同类规则、状态或选项比较使用表格；因果和取舍使用连贯段落。列表长度、段落数量和总字数按内容决定。

删除只有态度、没有事实或决定的修饰句。技术术语、业务术语和必要限定词保持准确，不使用同义词轮换制造变化。评价文档看它是否明确、可信和可执行，不追求模拟人的口头习惯或降低 AI 检测分数。

### 复用上游事实，交代本阶段新增内容

引用上游规则的可定位位置和必要版本，本阶段写新增细化、适用范围和交接。直接决定本地验收的条件可以在场景中重述，并绑定同一规则 ID；以一致性核验控制漂移。

不要用“详见相关文档”代替必要信息。引用不可读或版本不明时按现有合同处理。条件项只在流程允许时记录带原因的 `not-applicable`；命中的要求和必要异常场景应完整展示。

## 3. 各阶段怎么写

| 阶段 | 正文优先回答 | 本阶段需要写具体的内容 |
|---|---|---|
| 研究 | 已知什么，证据支持到哪里？ | 结论与来源、反证、限制分开；建议与事实区分 |
| Plan | 谁遇到什么问题，本期为什么这样取舍？ | 业务故事、MVP / 非目标、优先级依据、成功标准的确认情况、关键未决项 |
| Spec | 什么条件下，系统必须怎样表现？ | 规则与验收对应；按影响面覆盖成功、拒绝、边界、状态变化和恢复 |
| 产品设计 | 用户如何完成任务，失败后如何继续？ | 入口、操作、反馈、状态和恢复路径；引用 Spec，保留设计待确认项 |
| 工程契约 | 实现必须遵守什么，哪些地方有取舍？ | 精确协议与解释正文配合；标识、版本、范围及约束保持可核验 |
| Ticket | 本切片交付什么，如何证明完成？ | 窄而完整的行为、依赖、验收、公共测试 seam、当前合同及验证证据 |
| 审查 | 哪个具体条件下存在什么问题？ | 定位、触发条件、影响、依据与修复建议；推测和已复现问题分开 |
| 发布 / 复盘 | 验证了什么，还剩什么风险或决定？ | 实际验证范围、未覆盖部分、发布决定或失误机制与改进行动 |

这些指引帮助填写既有模板，不新增必填字段、阶段或门禁。Plan 不提前承诺详细 API 和工程实现；Spec 的例子不代替完整规则；Ticket 不重新设计已冻结行为。

## 4. 进度与会签提示

仅在用户询问状态、阶段切换或出现阻塞时，简短展示四项信息：**当前阶段、当前阻塞、谁处理、下一动作**。可以用一句话或四行表达，不要求表格。普通问题直接回答；其他进度更新只说明本轮有意义的变化，状态未变时不重复整套说明。

状态读取已有 checkpoint 和适用验证结果，不建立或要求用户填写另一套状态文件。未核验的阶段或阻塞情况写“待核验”；只有当前适用证据支持时才能写“无阻塞”。证据过期应明确指出过期输入及恢复动作，不能沿用历史通过结论。责任人按已有登记填写，缺失写“未登记”，不自行指派；下一动作说明如何补齐登记或核验。

默认只展示当前需要处理的事项，证据路径按需展开。查看状态本身不改文件，也不触发全套验证；推进阶段时仍执行原有适用校验。已授权且 Agent 可以完成的动作继续执行，避免把操作转交用户。

请求决定时展示当前版本、推荐方案及理由、实质选项和取舍、风险、批准范围与后续动作，遵守既有用户决定协议。可以突出当前最重要的问题，但所有影响决定的阻塞和选项都应可见。一次回复需要多个相互独立的决定时，分别说明各自影响。

示例：“规则说明已补齐。成功标准仍缺统计口径，负责人需在 Plan 进入 Spec 前确认；当前材料尚不能支持流转。”这类表述需要实际资产支持，不能成为固定的完成话术。

## 5. 起草与修订时的检查

1. 确认文档读者、当前阶段、权威输入和允许改动的范围；区分从事实起草与对既有正文作等义改写。
2. 起草时按本阶段的问题组织内容；修订时先列出必须保留的规则和约束，再调整文字。
3. 对照输入检查有无新增承诺、规则丢失、范围扩大、责任转移或不确定性被抹去。发现源资产冲突时记录并回交，不自行选一个版本。
4. 检查正文、摘要、表格和状态是否一致；验证适用的引用、结构和合同。自检结论不代替独立审查或批准。

规则、例外、证据或状态变化属于实质差异，不能被“字数减少”抵消。不要只用禁用词扫描或模型给自己的分数判断效果。
