/bin/zsh -lc "node --input-type=module <<'NODE'
import fs from 'node:fs';
import {createHash} from 'node:crypto';
import {spawnSync} from 'node:child_process';
import {readRepositoryMode} from './scripts/lib/repository-mode.mjs';
import {validateNextRoute} from './scripts/lib/lifecycle-transition.mjs';
const root = process.cwd();
const sha = ref => 'sha256:' + createHash('sha256').update(fs.readFileSync(ref)).digest('hex');
const refs = fs.readdirSync('research', {recursive:true}).map(p => 'research/' + p).filter(p => fs.lstatSync(p).isFile()).sort();
const before = Object.fromEntries(refs.map(ref => [ref, sha(ref)]));
const state = JSON.parse(fs.readFileSync('research/state.json', 'utf8'));
const record = JSON.parse(fs.readFileSync(state.research_verification.ref, 'utf8'));
const bindings = [state.research_verification, ...Object.values(record.inputs), record.stdout, record.stderr].map(item => ({ref:item.ref, expected:item.digest, actual:sha(item.ref), matches:sha(item.ref) === item.digest}));
const command = ['node', record.inputs.validator.ref, record.inputs.brief.ref, record.inputs.evidence.ref];
const started_at = new Date().toISOString();
const current = spawnSync(process.execPath, command.slice(1), {cwd:root, encoding:'utf8', timeout:30000, env:{...process.env,NODE_OPTIONS:'',NODE_PATH:''}});
const completed_at = new Date().toISOString();
const transition = validateNextRoute('work-unit.maintenance-research', null, state, {root});
const after = Object.fromEntries(refs.map(ref => [ref, sha(ref)]));
const result = {
  repository_mode:readRepositoryMode(root),
  source_audit:{ref:'research/source.txt', digest:sha('research/source.txt'), actual_text:fs.readFileSync('research/source.txt','utf8'), claim_id:'claim-001', scope:'仅核验本地合成样本声明的版本，不外推生产事实'},
  bindings,
  fresh_validation:{command,started_at,completed_at,exit_code:current.status,stdout:current.stdout,stderr:current.stderr,error:current.error?.message || null},
  transition_invocation:\"validateNextRoute('work-unit.maintenance-research', null, state, {root: process.cwd()})\",
  transition,
  research_records_unchanged:JSON.stringify(before) === JSON.stringify(after)
};
console.log(JSON.stringify(result,null,2));
if (current.status "'!== 0 || current.error || transition.result !== '"'allowed' || bindings.some(x=>"'!x.matches) || !result.research_records_unchanged) process.exitCode = 1;
NODE'

